program = '''from collections import Counter


def _runs(indices):
    if not indices:
        return []
    out = []
    start = prev = indices[0]
    for x in indices[1:]:
        if x != prev + 1:
            out.append((start, prev))
            start = x
        prev = x
    out.append((start, prev))
    return out


def _payload(run, size, limit):
    a, b = run
    if b - a + 1 == size:
        return range(a + 1, b)
    # A final tile clipped by the grid has no far-side border in the visible part.
    return range(a + 1, b + 1) if b == limit - 1 else range(a + 1, b)


def transform(grid):
    src = [row[:] for row in grid]
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    row_runs = _runs([r for r in range(h) if any(src[r][c] != 0 for c in range(w))])
    col_runs = _runs([c for c in range(w) if any(src[r][c] != 0 for r in range(h))])
    if not row_runs or not col_runs:
        return g
    tile_h = max(b - a + 1 for a, b in row_runs)
    tile_w = max(b - a + 1 for a, b in col_runs)
    row_payloads = [_payload(run, tile_h, h) for run in row_runs]
    col_payloads = [_payload(run, tile_w, w) for run in col_runs]

    full_payload = [
        src[r][c]
        for ri, (ra, rb) in enumerate(row_runs) if rb - ra + 1 == tile_h
        for ci, (ca, cb) in enumerate(col_runs) if cb - ca + 1 == tile_w
        for r in row_payloads[ri] for c in col_payloads[ci]
        if src[r][c] != 0
    ]
    if not full_payload:
        return g
    background = Counter(full_payload).most_common(1)[0][0]

    # Tile payload color and its row/column offsets, so connectors match the
    # full thickness of each repeated colored patch.
    payload_color = {}
    payload_rows = {}
    payload_cols = {}
    for ri, rows in enumerate(row_payloads):
        for ci, cols in enumerate(col_payloads):
            vals = [src[r][c] for r in rows for c in cols if src[r][c] != 0]
            if not vals:
                continue
            color = Counter(vals).most_common(1)[0][0]
            payload_color[ri, ci] = color
            payload_rows[ri, ci] = {r - row_runs[ri][0] for r in rows if any(src[r][c] == color for c in cols)}
            payload_cols[ri, ci] = {c - col_runs[ci][0] for c in cols if any(src[r][c] == color for r in rows)}

    for ri in range(len(row_runs)):
        positions = {}
        for ci in range(len(col_runs)):
            color = payload_color.get((ri, ci))
            if color is not None and color != background:
                positions.setdefault(color, []).append(ci)
        for color, inds in positions.items():
            for left, right in zip(inds, inds[1:]):
                rows = payload_rows[ri, left] & payload_rows[ri, right]
                for j in range(left, right):
                    for r_off in rows:
                        r = row_runs[ri][0] + r_off
                        for c in range(col_runs[j][1] + 1, col_runs[j + 1][0]):
                            g[r][c] = color

    for ci in range(len(col_runs)):
        positions = {}
        for ri in range(len(row_runs)):
            color = payload_color.get((ri, ci))
            if color is not None and color != background:
                positions.setdefault(color, []).append(ri)
        for color, inds in positions.items():
            for top, bottom in zip(inds, inds[1:]):
                cols = payload_cols[top, ci] & payload_cols[bottom, ci]
                for j in range(top, bottom):
                    for c_off in cols:
                        c = col_runs[ci][0] + c_off
                        for r in range(row_runs[j][1] + 1, row_runs[j + 1][0]):
                            g[r][c] = color
    return g
'''
